var frag=`
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 iResolution;
uniform vec2 iMouse;
uniform float iTime;
uniform int noctaves;
uniform float c[22];
float mousefactor;

float noise( in vec2 x )
{
  return sin(0.2*x.x)*sin(0.5*x.y);
}

const mat2 rot = mat2( 0.7,  0.8, -0.6,  0.2 ); //ebanut
float fbm ( in vec2 _st) {
    float v = 0.1;
    float a = 0.6;
    vec2 shift = 10.0*vec2(c[11],c[12]);
    for (int i = 0; i < 12; ++i) {//noprotect
    if(i>=noctaves)break;
        v += a * noise(_st);
        _st = rot*_st* 2.0 + shift;
        a *= 0.6;
    }
    return v;
}

void main() {
    vec2 mouse=iMouse/iResolution;
    vec2 st =(-iResolution.xy+2.0*gl_FragCoord.xy)/iResolution.y;//(gl_FragCoord.xy/iResolution.xy);//
    vec3 color = vec3(10.);
    vec2 q = vec2(7);
    q.x = fbm( st+vec2(c[0],c[1]*.01*iTime) );
    q.y = fbm( st+vec2(c[2],c[3]) );
    vec2 r = vec2(0.);

//play with the values here!
    r.x = fbm( st+ (18.0*mouse.x+0.4)*q+vec2(c[5],c[6]));
    r.y = fbm( st+ (20.0*mouse.y+0.5)*q*sin(.01*iTime)+vec2(c[8]*.05*iTime,c[9]));
    float f = fbm(st+c[10]*(r+length(q) ));
    color = smoothstep(vec3(0,0,255),vec3(0,25,255),color);
    color = mix(color,vec3(5,.105*(50.0+cos(1.8+.2*iTime)),20),r.y+length(q));//
   // color = mix(color,vec3(50*sin(.8*iTime),40,cos(.13*iTime)),length(r+q));//.2+.2*(1.0+cos(0.5+.3*iTime))
   // color = mix( color, vec3(29,255,85), dot(r,r) );
    color*=(1.5*f*f*f+1.8*f*f+1.7*f);
    color*=.4*vec3(1.85+r.x,0.45+q);
    color=pow(color, vec3(.75));
//

    gl_FragColor = vec4(color,1.);
}

`
var vert=`
//standard vertex shader
#ifdef GL_ES
      precision highp float;
    #endif
    #extension GL_OES_standard_derivatives : enable
    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;

